def _apply_army_pay_grant_effect(
    self, state: GameState, row, payload: Dict[str, object], dossier_id: int,
) -> int:
    """#1503：颁布缝一次消费拨饷载荷 — 扣库+销欠同事务（ADR 0023 clamp）。"""
    from ming_sim.flows import _apply_economy_list

    amount = int(payload.get("amount") or 0)
    if amount <= 0:
        raise ValueError("拨饷案卷 amount 必须为正数")
    account = str(
        payload.get("account") or payload.get("target_account") or ""
    ).strip()
    if account not in {"国库", "内库"}:
        raise ValueError("拨饷案卷 account 仅可为国库或内库")
    target_id = str(
        payload.get("target_id") or row.get("target_id") or ""
    ).strip()
    if str(payload.get("target_kind") or row.get("target_kind") or "") != "army" or not target_id:
        raise ValueError("拨饷案卷须指定 target_kind=army 与 target_id")
    origin_ref = f"dossier:{int(dossier_id)}"
    # 幂等：同案已有补饷流水则不二扣（ready 重放 / 重复 settle 护栏）。
    existing = [
        m for m in self.list_economy_moves_for_dossier(int(dossier_id))
        if str(m.get("purpose") or "") == "补饷"
    ]
    if existing:
        return abs(int(existing[0].get("delta") or 0))
    move = {
        "account": account,
        "delta": -amount,
        "category": str(payload.get("category") or "奉旨拨饷"),
        "reason": str(payload.get("reason") or row["decree_text"]),
        "purpose": "补饷",
        "target_kind": "army",
        "target_id": target_id,
        "origin_ref": origin_ref,
    }
    results = _apply_economy_list(
        self, state, [move], commit=False, require_origin=False,
    )
    spent = 0
    for item in results:
        if not isinstance(item, dict):
            continue
        if item.get("rejected"):
            raise ValueError(str(item.get("reason") or "拨饷落账被拒"))
        spent += abs(int(item.get("delta") or 0))
    return spent

def resolve_commitment_origin_ref(
    self, state: GameState, supplied_ref: str, *, origin_kind: str = "",
) -> str:
    """承诺创建写端：有本回合已颁案卷时，origin 单向归一到案卷。"""
    supplied = str(supplied_ref or "").strip()
    if supplied.startswith("dossier:"):
        try:
            dossier_id = int(supplied.split(":", 1)[1])
        except (TypeError, ValueError):
            raise ValueError("commitment origin_ref 案卷 id 非法")
        if self.get_decree_dossier(dossier_id) is None:
            raise ValueError("commitment origin_ref 指向不存在案卷")
        return supplied
    from ming_sim.materials import SECRET_ORDER_ORIGIN_PREFIX, is_secret_order_origin

    if is_secret_order_origin(supplied):
        try:
            secret_order_id = int(supplied[len(SECRET_ORDER_ORIGIN_PREFIX):])
        except (TypeError, ValueError):
            raise ValueError("commitment origin_ref 密令 id 非法")
        dossier = self.get_dossier_for_secret_order(secret_order_id)
        if dossier is None:
            raise ValueError("commitment origin_ref 指向无案卷密令")
        return f"dossier:{int(dossier['id'])}"
    if str(origin_kind or "") == "decree":
        row = self.conn.execute(
            "SELECT COUNT(*) AS n FROM decree_dossiers WHERE created_turn=?",
            (int(state.turn),),
        ).fetchone()
        if row is not None and int(row["n"] or 0) > 0:
            raise ValueError(
                "承诺 origin_ref 必须由产出它的明确案卷携带 dossier:<id>"
            )
    return supplied

def parse_affair_declaration(
    raw: object,
    *,
    allowed: frozenset[str] | None = None,
) -> dict[str, object]:
    """Typed LLM declaration only. No prose parsing."""
    if not isinstance(raw, Mapping):
        raise ValueError("事务声明须为对象")
    attach = str(raw.get("attach") or "").strip()
    permitted = ATTACH_BIRTH | ATTACH_RESULT_CLOSE if allowed is None else allowed
    if attach not in permitted:
        if attach == _ATTACH_CLOSE:
            raise ValueError("本阶段不能了结事务")
        if attach in ATTACH_BIRTH and permitted == ATTACH_RESULT_CLOSE:
            raise ValueError("顶层事务声明只接受了结")
        raise ValueError("事务声明 attach 不在本阶段")
    if attach == _ATTACH_NEW:
        name = str(raw.get("name") or "")
        origin = str(raw.get("origin") or "")
        if not name or not origin:
            raise ValueError("新事务声明须有名字与起因")
        key = str(raw.get("birth_key") or "").strip()
        identity = str(raw.get("identity") or "").strip()
        out: dict[str, object] = {"attach": _ATTACH_NEW, "name": name, "origin": origin}
        if key:
            out["birth_key"] = key
        if identity:
            out["identity"] = identity
        return out
    try:
        affair_id = parse_positive_affair_id(raw.get("affair_id"))
    except (TypeError, ValueError) as exc:
        raise ValueError(
            "了结须有 affair_id" if attach == _ATTACH_CLOSE else "接到已开事务须有 affair_id"
        ) from exc
    return {"attach": attach, "affair_id": affair_id}

def _payload_owned_dossier_for_origin(db: GameDB, origin_ref: object) -> Optional[Dict[str, object]]:
    """Resolve an authorized dossier through the canonical ownership policy."""
    text = str(origin_ref or "").strip()
    if not text.startswith("dossier:"):
        return None
    try:
        dossier_id = _parse_sqlite_id(text.split(":", 1)[1])
    except ValueError:
        return None
    row = db.get_decree_dossier(dossier_id)
    if row is None or not db.dossier_authorizes_effects(dossier_id):
        return None
    try:
        payload = row.get("payload") or json.loads(str(row.get("payload_json") or "{}"))
    except (TypeError, ValueError):
        return None
    if not isinstance(payload, dict):
        return None
    if dossier_action_policy(row.get("action_type"), payload)["effect_owner"] != "payload":
        return None
    return {**row, "payload": payload}

