def _submit_cli_decisions(session: GameSession, result) -> str:
    """CLI 文书批语：皇帝选择拟批或亲笔；不自动代选。"""
    if result is None or not result.awaiting:
        return "" if result is None else result.report
    choices = []
    for row in list(result.decisions or []) or session.pending_decisions():
        print(f"\n{row['title']}\n{row['context']}")
        for idx, option in enumerate(row["options"], 1):
            print(f"{idx}. {option['label']} {option.get('hint', '')}")
        explicit = str(row.get("event_id") or "").startswith(("dossier:", "deliberation:"))
        while True:
            raw = input("拟批编号 / 亲笔批语" + ("（m 另旨·中旨）" if row["kind"] == "rescript_draft" else "") + "：")
            choice = {"decision_key": row["decision_key"]}
            if raw.isdecimal() and 1 <= int(raw) <= len(row["options"]):
                option = row["options"][int(raw) - 1]
                choice.update(label=option["label"], hint=option.get("hint", ""))
                if explicit:
                    choice["action"] = option.get("dossier_decision") or option.get("action") or ""
                choice["note"] = input("附批（可空）：")
                break
            if not explicit and raw.strip():
                if raw == "m" and row["kind"] == "rescript_draft":
                    choice.update(action="midzhi", note=input("御笔旨意："))
                    if not choice["note"].strip():
                        continue
                else:
                    choice["note"] = raw
                break
            print("请选择编号；不代选。")
        choices.append(choice)
    return session.submit_hitl_choices(choices, write_gate=_cli_write_gate(session))

def _draft_intent_character_roster_facts(content: Any) -> str:
    """#1428：把 content.characters 的 name+aliases 编成抽取接地事实块。

    接地=结构化事实注入（ADR 0142）；不在此做散文截断修复/子串归一。
    参与人 character_id 须填规范名；别名仅作识别线索，输出仍归规范名。
    资格与可召面同口径：_is_summonable_court_minister（身份归一∧非宗藩∧非未仕；#1317 r2）。
    无 db 时用 content 静态 power_id（#125 live 翻转不扩）。身份归一另由 _find_existing_minister
    吃（含未仕/宗藩别名）；事实块只供可召朝臣接地，不倾倒待铨诸生。
    """
    characters = getattr(content, "characters", None) if content is not None else None
    if not characters:
        return ""
    from ming_sim.session import _is_summonable_court_minister

    lines: List[str] = []
    for key, ch in characters.items():
        if not _is_summonable_court_minister(ch):
            continue
        name = str(getattr(ch, "name", None) or key or "").strip()
        if not name:
            continue
        aliases = [
            str(a).strip()
            for a in (getattr(ch, "aliases", None) or [])
            if str(a).strip() and str(a).strip() != name
        ]
        if aliases:
            lines.append(f"{name}（别名：{'、'.join(aliases)}）")
        else:
            lines.append(name)
    if not lines:
        return ""
    return (
        "【在册人物规范名+别名】参与人 character_id 必须从此表规范名选取；"
        "见到别名须归一为对应规范名；不得截短、不得自造未列之名。\n"
        + "\n".join(lines)
        + "\n"
    )

